  protocols?: string[]
  reconnect: ReconnectPolicy
  heartbeat: HeartbeatPolicy
  onMessage: (message: ServerMessage) => void
  onStatus?: (status: SocketStatus) => void
  onTelemetry?: (event: RealtimeTelemetryEvent) => void
